import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷一·38","description":"易小帖 - 卷一·38","frontmatter":{"title":"卷一·38","description":"易小帖 - 卷一·38"},"headers":[],"relativePath":"classics/yixiaotie/038.md","filePath":"classics/yixiaotie/038.md"}'),o={name:"classics/yixiaotie/038.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷一·38",tabindex:"-1"},[r("卷一·38 "),e("a",{class:"header-anchor",href:"#卷一·38","aria-label":"Permalink to “卷一·38”"},"​")],-1),e("p",null,"明夷「夷於左股」，左在右後，即師卦左次可驗。惟蘇子瞻雲：爻言左右，猶言內外也。在我之上則於我為左，是以左在上，右在下，不知所據。若鄭康成說，以夷於左股為睇於左股，旁視曰睇，謂六二視九三則似左在上矣。然其解謂六二辰在酉，酉是西方，九三體在震，震是東方，六二下離為目，九三辰得巽氣為股，六二有明德，欲承九三，故雲睇於左股，則仍以方位言，左東右西，以西方之酉借離目以視東方巽氣之股，但指東西不拘上下，與蘇說又不同。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
